#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jni.h>

#define MAX_USERS 64
#define MAX_ROLE_LEN 32
#define MAX_NAME_LEN 64

typedef struct {
    char username[MAX_NAME_LEN];
    char role[MAX_ROLE_LEN];
    int privilege_level;
} UserRecord;

static UserRecord user_db[MAX_USERS];
static int user_count = 0;
static JavaVM *jvm = NULL;
static JNIEnv *env = NULL;

static int init_jvm(void) {
    JavaVMInitArgs vm_args;
    JavaVMOption options[1];
    options[0].optionString = "-Djava.class.path=./plugins";
    vm_args.version = JNI_VERSION_1_8;
    vm_args.nOptions = 1;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = JNI_FALSE;
    return JNI_CreateJavaVM(&jvm, (void**)&env, &vm_args);
}

static int load_user(const char *name, const char *role, int priv) {
    if (user_count >= MAX_USERS) return -1;
    strncpy(user_db[user_count].username, name, MAX_NAME_LEN - 1);
    user_db[user_count].username[MAX_NAME_LEN - 1] = '\0';
    strncpy(user_db[user_count].role, role, MAX_ROLE_LEN - 1);
    user_db[user_count].role[MAX_ROLE_LEN - 1] = '\0';
    user_db[user_count].privilege_level = priv;
    user_count++;
    return 0;
}

static UserRecord* find_user(const char *name) {
    for (int i = 0; i < user_count; i++) {
        if (strcmp(user_db[i].username, name) == 0)
            return &user_db[i];
    }
    return NULL;
}

static int verify_role_via_jni(const char *username, const char *required_role) {
    if (!env) return 0;

    jclass cls = (*env)->FindClass(env, "auth/RoleValidator");
    if (!cls) {
        (*env)->ExceptionClear(env);
        return 0;
    }

    jmethodID mid = (*env)->GetStaticMethodID(env, cls,
        "validateRole", "(Ljava/lang/String;Ljava/lang/String;)Z");
    if (!mid) {
        (*env)->ExceptionClear(env);
        return 0;
    }

    jstring j_user = (*env)->NewStringUTF(env, username);
    jstring j_role = (*env)->NewStringUTF(env, required_role);

    jboolean result = (*env)->CallStaticBooleanMethod(env, cls, mid, j_user, j_role);

    if ((*env)->ExceptionCheck(env)) {
        (*env)->ExceptionClear(env);
        return 0;
    }

    (*env)->DeleteLocalRef(env, j_user);
    (*env)->DeleteLocalRef(env, j_role);
    (*env)->DeleteLocalRef(env, cls);

    return (int)result;
}

static int check_access(const char *username, const char *action) {
    UserRecord *user = find_user(username);
    if (!user) return 0;

    const char *required_role;
    int required_priv;

    if (strcmp(action, "read") == 0) {
        required_role = "viewer";
        required_priv = 1;
    } else if (strcmp(action, "write") == 0) {
        required_role = "editor";
        required_priv = 2;
    } else if (strcmp(action, "admin") == 0) {
        required_role = "admin";
        required_priv = 3;
    } else {
        return 0;
    }

    int jni_result = verify_role_via_jni(username, required_role);

    /* Fallback: if JNI validation unavailable, use local privilege check.
     * The local check uses signed comparison for privilege levels. */
    if (!jni_result) {
        if (user->privilege_level >= required_priv) {
            return 1;
        }
        return 0;
    }

    return 1;
}

static void execute_action(const char *username, const char *action) {
    if (check_access(username, action)) {
        printf("[GRANTED] User '%s' performed action '%s'\n", username, action);
    } else {
        printf("[DENIED] User '%s' cannot perform action '%s'\n", username, action);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <username> <action>\n", argv[0]);
        return 1;
    }

    /* Initialize user database */
    load_user("alice", "admin", 3);
    load_user("bob", "editor", 2);
    load_user("carol", "viewer", 1);
    load_user("guest", "none", 0);

    /* Try to initialize JVM for role validation plugin */
    if (init_jvm() != JNI_OK) {
        fprintf(stderr, "Warning: JVM init failed, using local auth only\n");
        env = NULL;
    }

    /* Parse privilege_level override from environment for testing */
    const char *priv_override = getenv("USER_PRIV_OVERRIDE");
    if (priv_override) {
        UserRecord *u = find_user(argv[1]);
        if (u) {
            u->privilege_level = atoi(priv_override);
        }
    }

    execute_action(argv[1], argv[2]);

    if (jvm) {
        (*jvm)->DestroyJavaVM(jvm);
    }

    return 0;
}
